WITH metrics AS (SELECT *, PERCENT_RANK() OVER (ORDER BY amount DESC NULLS LAST) amount_percent_rank, AVG(amount) OVER (PARTITION BY order_id, status ORDER BY paid_at, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) amount_avg_5_prior, AVG(amount) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) amount_avg_3_prior FROM payments WHERE paid_at < '2025-01-01') SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, DATE_TRUNC('WEEK', paid_at) AS week_start, ROUND(SUM(amount_avg_3_prior) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS amount_avg_3_prior_per_failed, AVG(amount_percent_rank) FILTER (WHERE method = 'bank_transfer') AS bank_transfer_avg_amount_percent_rank, SUM(CASE WHEN status = 'SUCCESS' THEN amount_avg_3_prior ELSE 0 END) AS success_amount_avg_3_prior FROM metrics GROUP BY ROLLUP (DATE_TRUNC('QUARTER', paid_at), DATE_TRUNC('WEEK', paid_at)) ORDER BY quarter_start;
